select.where:
m.is_active = 1
AND ( m.product_name like concat('%', #{keyword}, '%') OR m.product_alias like concat('%', #{keyword}, '%') OR m.product_english_name like concat('%', #{keyword}, '%') OR m.cas_number like concat('%', #{keyword}, '%') OR m.company_name like concat('%', #{keyword}, '%') )
AND m.category_id = #{filters.categoryId}
AND m.company_name like concat('%', #{filters.supplier}, '%')
AND EXISTS ( SELECT 1 FROM msds_hazard hz WHERE hz.msds_id = m.id AND (
hz.hazard_category like concat('%', #{hk}, '%') OR hz.fire_explosion_hazards like concat('%', #{hk}, '%') OR hz.health_hazards like concat('%', #{hk}, '%')
) )
AND m.update_time >= #{filters.updateTimeFrom}
AND m.update_time <= #{filters.updateTimeTo}

mapper.select:
select k.kw as keyword, count(distinct case when hz.hazard_category like concat('%', k.kw, '%') or hz.fire_explosion_hazards like concat('%', k.kw, '%') or hz.health_hazards like concat('%', k.kw, '%') then m.id end) as docCount from msds_main m join msds_hazard hz on hz.msds_id = m.id join (
select #{kw} as kw
) k where m.is_active = 1 group by k.kw

SELECT m.*
FROM msds_main m
WHERE m.is_active = 1
AND m.id != #{msdsId}
AND (
    m.category_id = (SELECT category_id FROM msds_main WHERE id = #{msdsId})
    OR m.company_name = (SELECT company_name FROM msds_main WHERE id = #{msdsId})
)
ORDER BY m.update_time DESC
LIMIT #{limit}
